$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Resume simulation':'Pause simulation');};document.querySelectorAll('[data-speed]').forEach(b=>b.onclick=()=>{speed=Number(b.dataset.speed);document.querySelectorAll('[data-speed]').forEach(x=>x.classList.toggle('active',x===b));});
$('reset').onclick=()=>{if(!physics)return;pilot?.exit();if(pilot)pilot.shots=0;playerMissiles=playerHits=playerBuildingHits=0;physics.reset();for(const c of physics.chunks){syncChunk(c);chunkBatches[c.type].setColorAt(c.index,new THREE.Color(c.tint));}for(const o of Object.values(chunkBatches))o.instanceColor.needsUpdate=true;for(const p of projectiles)scene.remove(p.mesh);projectiles.length=particles.length=tracers.length=0;for(const p of [smokePool,flashPool,sparkPool])p.count=0;tracerGeo.setDrawRange(0,0);for(const t of tanks){t.root.position.copy(t.start);t.cooldown=1.1+t.i*.65+t.team*.6;}for(const h of helicopters){h.cooldown=2+h.team+h.i*1.5;h.phase=h.team*Math.PI+h.i*.7;h.returning=null;const side=h.team===0?-1:1;h.root.position.set(Math.cos(h.phase)*26+side*10,27+Math.sin(h.phase)*1.4+h.i*5,Math.sin(h.phase)*30);h.root.rotation.set(0,Math.atan2(-Math.sin(h.phase),Math.cos(h.phase)),Math.sin(h.phase)*.06,'YXZ');h.rotor.rotation.y=0;h.tail.rotation.x=0;}simTime=shotsFired=0;soldierCrowd?.reset();weaponImpacts.shell=weaponImpacts.rocket=0;impactLog=[];feed('District rebuilt. Both divisions regrouping.');updateStats();};
$('help').onclick=()=>$('guide').showModal();$('close-guide').onclick=()=>$('guide').close();$('fullscreen').onclick=()=>{const shell=document.querySelector('.viewer');if(document.fullscreenElement)document.exitFullscreen?.();else if(shell.requestFullscreen)shell.requestFullscreen().catch(()=>feed('Fullscreen unavailable in this browser.'));else feed('Use landscape orientation for a wider view.');};
const keys=new Set();let heightInput=0;window.addEventListener('keydown',e=>{if(pilot?.active)return;if(['INPUT','SELECT','BUTTON','A'].includes(e.target.tagName))return;if(['w','a','s','d','q','e','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();keys.add(e.key.toLowerCase());});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();heightInput=0;});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();heightInput=0;}});for(const [id,sign]of [['rise',1],['lower',-1]]){const b=$(id);b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);heightInput=sign;};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>heightInput=0;}
function updateCamera(dt){if(pilot?.active){pilot.updateCamera();return;}if(view==='infantry'&&soldierCrowd){const p=soldierCrowd.position();camera.position.lerp(p.clone().add(new THREE.Vector3(3.5,2.1,3.0)),1-Math.exp(-4*dt));controls.target.lerp(p.add(new THREE.Vector3(0,1.05,0)),1-Math.exp(-4*dt));}else if(view==='tank'&&tanks[0]){const goal=tanks[0].root.position.clone().add(new THREE.Vector3(-9,6,10)),target=tanks[0].root.position.clone().add(new THREE.Vector3(3,1,0));camera.position.lerp(goal,1-Math.exp(-3*dt));controls.target.lerp(target,1-Math.exp(-3*dt));}else if(view==='air'&&helicopters[0]){camera.position.lerp(helicopters[0].root.position.clone().add(new THREE.Vector3(10,5,14)),1-Math.exp(-3*dt));controls.target.lerp(helicopters[0].root.position,1-Math.exp(-3*dt));}
 let x=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0),z=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0),y=(keys.has('e')?1:0)-(keys.has('q')?1:0)+heightInput;
 if(x||z||y){view='free';camera.getWorldDirection(v3);v3.y=0;v3.normalize();const right=new THREE.Vector3().crossVectors(v3,new THREE.Vector3(0,1,0));const delta=v3.multiplyScalar(z).addScaledVector(right,x);delta.y=y;delta.multiplyScalar(dt*(keys.has('shift')?28:12));if(camera.position.y+delta.y<1)delta.y=0;camera.position.add(delta);controls.target.add(delta);$('camera-label').textContent='OBSERVER / FREE ROAM';}controls.update();}
function updateStats(){if(!physics)return;const s=physics.stats();$('hits').textContent=s.impacts;$('debris').textContent=s.detached;$('active').textContent=s.activeBodies;$('time').textContent=String(Math.floor(simTime/60)).padStart(2,'0')+':'+String(Math.floor(simTime%60)).padStart(2,'0');}
async function initialize(){try{const [g,data,infantryModel,infantryMotion,cockpit]=await Promise.all([new GLTFLoader().loadAsync('city-assets/city-kit.glb'),fetch('city-assets/city-layout.json').then(r=>{if(!r.ok)throw Error('layout request failed');return r.json()}),new GLTFLoader().loadAsync('city-assets/soldier-parts.glb'),fetch('city-assets/soldier-motion.json').then(r=>{if(!r.ok)throw Error('soldier motion request failed');return r.json()}),new GLTFLoader().loadAsync('city-assets/cockpit.glb')]);extract(g);layout=data;soldierParts=infantryModel;soldierMotion=infantryMotion;physics=new DestructionWorld({maxDynamic:innerWidth<700?110:160,onDetach:c=>{chunkBatches[c.type]?.setColorAt(c.index,new THREE.Color(c.tint).multiplyScalar(.78));if(chunkBatches[c.type]?.instanceColor)chunkBatches[c.type].instanceColor.needsUpdate=true;},onFreeze:syncChunk,onCollapse:(id,f)=>{feed(id+' · structural supports failed. Floors '+(f+1)+' and above collapsing.');const b=buildingRecords.get(id);emitParticle('smoke',new THREE.Vector3(b.x,f*3+2,b.z),18,2);}});addChunks();makeTanks();makeHelicopters();makeTroops();addProps();pilot=new HelicopterPilot({scene,camera,controls,canvas:renderer.domElement,helicopters,cockpit,getSections:()=>physics.chunks,isPaused:()=>paused,onEnter:h=>{view='pilot';paused=false;speed=1;keys.clear();heightInput=0;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pause simulation');document.querySelectorAll('[data-speed]').forEach(b=>{b.disabled=true;b.classList.toggle('active',b.dataset.speed==='1')});document.querySelectorAll('[data-view]').forEach(b=>b.classList.remove('selected'));feed('Manual flight · drag to aim, then launch a rocket.');},onExit:h=>{h.phase-=simTime*.055;view='free';keys.clear();document.querySelectorAll('[data-speed]').forEach(b=>b.disabled=false);$('camera-label').textContent='OBSERVER / FREE ORBIT';feed('Pilot released. Rotorcraft returning to its patrol.');},onMissile:(from,to,team)=>fire(from,to,team,'rocket',true)});loaded=true;updateCombat(0);setView('overview');$('loading').style.display='none';feed('North and South divisions entering the district.');}catch(e){console.error(e);$('loading').innerHTML='<b>The district could not load.</b><span>Reload this page to try again.</span>';}}
function resize(){const w=viewport.clientWidth,h=viewport.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix();}new ResizeObserver(resize).observe(viewport);resize();if(innerWidth<700)$('camera-hint').innerHTML='DRAG TO ORBIT <b>·</b> PINCH TO ZOOM <b>·</b> TWO FINGERS TO PAN';
let previous=performance.now(),fpsStart=previous,frames=0;function animate(now){requestAnimationFrame(animate);const elapsed=Math.min((now-previous)/1000,.25);previous=now;const dt=Math.min(elapsed,.075);if(loaded&&!paused){const step=dt*speed;simTime+=step;updateCombat(step);physics.step(step);for(const c of physics.dynamic)syncChunk(c);updateEffects(step);}updateCamera(elapsed);pilot?.updateMarkers();renderer.render(scene,camera);frames++;if(now-fpsStart>1000){const fps=Math.round(frames*1000/(now-fpsStart));$('fps').textContent=fps+' FPS';slowSeconds=fps<25?slowSeconds+1:0;if(slowSeconds>=3&&renderer.getPixelRatio()>.65){renderer.setPixelRatio(Math.max(.65,renderer.getPixelRatio()-.25));resize();slowSeconds=0;}fpsStart=now;frames=0;updateStats();}}
initialize();requestAnimationFrame(animate);
window.battleDiagnostics=()=>({loaded,paused,speed,view,seconds:simTime,shotsFired,weaponImpacts:{...weaponImpacts},army:{tanks:tanks.length,helicopters:helicopters.length,infantry:troops.length},physics:physics?.stats(),camera:camera.position.toArray(),pilot:pilot?.diagnostics(),playerMissiles,playerHits,playerBuildingHits,helicopters:helicopters.map(h=>({team:h.team,index:h.i,position:h.root.position.toArray(),visible:h.root.visible})),infantry:soldierCrowd?.diagnostics(),triangles:renderer.info.render.triangles,drawCalls:renderer.info.render.calls,debris:physics?.dynamic.slice(0,3).map(c=>({position:[c.body.position.x,c.body.position.y,c.body.position.z],quaternion:[c.body.quaternion.x,c.body.quaternion.y,c.body.quaternion.z,c.body.quaternion.w]}))});
